result.output:
200		}
201	
202		// Route to appropriate handler
203		if commitRef != "" {
204			return runExplainCommit(ctx, w, commitRef, noPager, verbose, full, searchAll)
205		}
206		if checkpointID != "" {
207			return runExplainCheckpoint(ctx, w, errW, checkpointID, noPager, verbose, full, rawTranscript, generate, force, searchAll)
208		}
209	
210		// Default or with session filter: show list view (optionally filtered by session)
211		return runExplainBranchWithFilter(ctx, w, noPager, sessionID)
212	}
