467		// Check if transcript exists
468		if len(content.Transcript) == 0 {
469			return fmt.Errorf("checkpoint %s has no transcript to summarize", checkpointID)
470		}
471	
472		// Scope the transcript to only this checkpoint's portion
473		scopedTranscript := scopeTranscriptForCheckpoint(content.Transcript, content.Metadata.GetTranscriptStart(), content.Metadata.Agent)
