23	// Agent implements agent.Agent by delegating to an external binary.
24	// Each method invokes a subcommand on the binary and parses the JSON response.
25	type Agent struct {
26		binaryPath string
27		info       *InfoResponse
28	}
29	
30	// New creates an Agent by calling the binary's "info" subcommand
31	// to cache its metadata. Returns an error if the binary cannot be invoked or returns
32	// invalid/incompatible protocol data. The provided context bounds the "info" call;
33	// pass a context with a deadline to limit how long discovery waits for each binary.
34	func New(ctx context.Context, binaryPath string) (*Agent, error) {
35		ea := &Agent{binaryPath: binaryPath}
36	
37		stdout, err := ea.run(ctx, nil, "info")
38		if err != nil {
39			return nil, fmt.Errorf("info: %w", err)
40		}
41	
42		var info InfoResponse
43		if err := json.Unmarshal(stdout, &info); err != nil {
44			return nil, fmt.Errorf("info: invalid JSON: %w", err)
45		}
46	
47		if info.ProtocolVersion != ProtocolVersion {
48			return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
49				info.ProtocolVersion, ProtocolVersion)
50		}
51	
52		ea.info = &info
53		return ea, nil
54	}
