211		const maxParseHookBytes = 10 * 1024 * 1024 // 10 MB
212		data, err := io.ReadAll(io.LimitReader(stdin, maxParseHookBytes))
213		if err != nil {
214			return nil, fmt.Errorf("parse-hook: read stdin: %w", err)
