217		if err != nil {
218			return nil, fmt.Errorf("parse-hook: %w", err)
219		}
220		// null means no lifecycle significance
221		if bytes.Equal(bytes.TrimSpace(stdout), []byte("null")) {
222			return nil, nil //nolint:nilnil // protocol contract: null = no event
223		}
224		var event eventJSON
225		if err := json.Unmarshal(stdout, &event); err != nil {
226			return nil, fmt.Errorf("parse-hook: invalid JSON: %w", err)
227		}
228		return event.toEvent()
229	}
