399	// run executes a subcommand on the external binary and returns stdout bytes.
400	// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
401	// included in the returned error.
402	func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
403		// Apply a default timeout when the caller hasn't set a deadline, so a hung
404		// external binary can't block the CLI (or git hooks) indefinitely.
405		if _, ok := ctx.Deadline(); !ok {
406			var cancel context.CancelFunc
407			ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
408			defer cancel()
409		}
410		cmd := exec.CommandContext(ctx, e.binaryPath, args...)
411		// Ensure I/O goroutines are released shortly after the process is killed,
412		// so cmd.Run() doesn't block waiting for pipe reads.
413		cmd.WaitDelay = 3 * time.Second
414	
415		// Set environment: repo root + protocol version
416		cmd.Env = append(cmd.Environ(),
417			"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
418		)
419		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
420			cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
421			cmd.Dir = repoRoot
422		}
423	
424		if stdin != nil {
425			cmd.Stdin = bytes.NewReader(stdin)
426		}
427	
428		const maxOutputBytes = 10 * 1024 * 1024 // 10 MB
429	
430		var stdoutBuf, stderrBuf bytes.Buffer
431		stdoutLW := &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
432		stderrLW := &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
433		cmd.Stdout = stdoutLW
434		cmd.Stderr = stderrLW
435	
436		if err := cmd.Run(); err != nil {
437			errMsg := strings.TrimSpace(stderrBuf.String())
438			if errMsg != "" {
439				return nil, fmt.Errorf("%s: %s", args[0], errMsg)
440			}
441			return nil, fmt.Errorf("%s: %w", args[0], err)
442		}
443	
444		if stdoutLW.truncated {
445			return nil, fmt.Errorf("%s: output exceeded %d byte limit", args[0], maxOutputBytes)
446		}
447	
448		return stdoutBuf.Bytes(), nil
449	}
450	
451	// --- Helpers ---
452	
453	// limitedWriter wraps a bytes.Buffer and stops writing after limit bytes,
454	// preventing unbounded memory growth from external process output.
455	type limitedWriter struct {
456		buf       *bytes.Buffer
457		limit     int
458		truncated bool
459	}
460	
461	func (w *limitedWriter) Write(p []byte) (int, error) {
462		remaining := w.limit - w.buf.Len()
463		if remaining <= 0 {
464			w.truncated = true
465			return len(p), nil // discard, but report success so the process isn't killed
466		}
467		if len(p) > remaining {
468			p = p[:remaining]
469			w.truncated = true
470		}
471		n, err := w.buf.Write(p)
472		if err != nil {
473			return n, fmt.Errorf("writing to limited buffer: %w", err)
474		}
475		return n, nil
476	}
