1043	func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
1044		if err := ctx.Err(); err != nil {
1045			return nil, err //nolint:wrapcheck // Propagating context cancellation
1046		}
1047	
1048		tree, err := s.getSessionsBranchTree()
1049		if err != nil {
1050			return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
1051		}
1052	
1053		var checkpoints []CommittedInfo
1054	
1055		// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
1056		_ = WalkCheckpointShards(s.repo, tree, func(checkpointID id.CheckpointID, cpTreeHash plumbing.Hash) error { //nolint:errcheck // callback never returns errors
1057			checkpointTree, cpTreeErr := s.repo.TreeObject(cpTreeHash)
1058			if cpTreeErr != nil {
1059				return nil //nolint:nilerr // skip unreadable entries, continue walking
1060			}
1061	
1062			info := CommittedInfo{
1063				CheckpointID: checkpointID,
1064			}
1065	
1066			// Get details from root metadata file (CheckpointSummary format)
1067			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
1068				if content, contentErr := metadataFile.Contents(); contentErr == nil {
1069					var summary CheckpointSummary
1070					if err := json.Unmarshal([]byte(content), &summary); err == nil {
1071						info.CheckpointsCount = summary.CheckpointsCount
1072						info.FilesTouched = summary.FilesTouched
1073						info.SessionCount = len(summary.Sessions)
1074	
1075						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
1076						if len(summary.Sessions) > 0 {
1077							latestIndex := len(summary.Sessions) - 1
1078							latestDir := strconv.Itoa(latestIndex)
1079							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
1080								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
1081									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
1082										var sessionMetadata CommittedMetadata
1083										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
1084											info.Agent = sessionMetadata.Agent
1085											info.SessionID = sessionMetadata.SessionID
1086											info.CreatedAt = sessionMetadata.CreatedAt
1087										}
1088									}
1089								}
1090							}
1091						}
1092					}
1093				}
1094			}
1095	
1096			checkpoints = append(checkpoints, info)
1097			return nil
1098		})
1099	
1100		// Sort by time (most recent first)
1101		sort.Slice(checkpoints, func(i, j int) bool {
1102			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
1103		})
1104	
1105		return checkpoints, nil
1106	}
