+	}
+	var hasTool bool
+	for _, entry := range condensed {
+		if entry.Type == "tool" && entry.ToolName == "write" {
+			hasTool = true
+		}
+	}
+	if !hasTool {
+		t.Errorf("expected condensed entry with tool name 'write', got: %+v", condensed)
+	}
